from collections import defaultdict, deque


def is_unique_reconstruction(nums, sequences):
    in_degree = {v: 0 for v in nums}
    graph = defaultdict(set)
    for seq in sequences:
        for i in range(len(seq) - 1):
            a, b = seq[i], seq[i + 1]
            if b not in graph[a]:
                graph[a].add(b)
                in_degree[b] += 1
    queue = deque(v for v in nums if in_degree[v] == 0)
    order = []
    while queue:
        if len(queue) > 1:
            return False
        node = queue.popleft()
        order.append(node)
        for nb in graph[node]:
            in_degree[nb] -= 1
            if in_degree[nb] == 0:
                queue.append(nb)
    return order == nums
